public sealed class DocumentaryVariantDependencyResolver(IDocumentaryPhysicalArtifactRegistry registry,IDocumentaryContentIdentityFactory identities):IDocumentaryVariantDependencyResolver {
 public async Task<DocumentaryVariantDependencyResolution> ResolveAsync(DocumentaryVariantCompositionRequest r,DocumentaryProductionWorkspace workspace,CancellationToken token){ArgumentNullException.ThrowIfNull(r);token.ThrowIfCancellationRequested();if(r.SceneAssets.Count==0)return Fail(DocumentaryProductionFailureCode.SourceArtifactMissing,"No finalized scene videos were supplied.");if(r.CorrelationId!=r.AssetPlan.CorrelationId||r.CorrelationId!=r.MediaVariant.CorrelationId)return Fail(DocumentaryProductionFailureCode.SourceArtifactInvalid,"Variant correlation is invalid.");if(r.SceneAssets.Select(x=>x.AssetId).Distinct(StringComparer.Ordinal).Count()!=r.SceneAssets.Count)return Fail(DocumentaryProductionFailureCode.SourceArtifactInvalid,"Scene dependencies are duplicated.");var entries=new List<DocumentaryResolvedVariantScene>();foreach(var source in r.SceneAssets){var dep=r.AssetPlan.Dependencies.Where(x=>x.SourceAssetId==source.AssetId).ToArray();if(dep.Length!=1)return Fail(DocumentaryProductionFailureCode.SourceArtifactInvalid,"Scene sequence metadata is missing or ambiguous.");var d=await registry.GetAsync(source.AssetId,token);if(d is null)return Fail(DocumentaryProductionFailureCode.SourceArtifactMissing,"A finalized scene video is missing.");if(source.AssetType!=DocumentaryMediaAssetType.SceneVideo||source.AssetFormat!=DocumentaryMediaAssetFormat.Mp4||source.CorrelationId!=r.CorrelationId||d.CorrelationId!=r.CorrelationId||!string.Equals(d.ContentType,"video/mp4",StringComparison.OrdinalIgnoreCase)||d.Length<=0||!File.Exists(d.PhysicalPath)||DocumentaryPathComparison.IsBelow(workspace.AttemptsDirectory,d.PhysicalPath)||d.DurationMilliseconds is null or <=0||d.Width is null or <=0||d.Height is null or <=0||d.FrameRate is null or <=0||!IsLowercaseSha256(d.Checksum)||!identities.IsValid(d.ContentIdentity)||!string.Equals(d.ContentIdentity,"sha256:"+d.Checksum,StringComparison.Ordinal))return Fail(DocumentaryProductionFailureCode.SourceArtifactInvalid,"A finalized scene video is invalid.");var scene=r.MediaVariant.Scenes.FirstOrDefault(x=>x.Sequence==dep[0].Sequence);if(scene is null)return Fail(DocumentaryProductionFailureCode.SourceArtifactInvalid,"A scene does not belong to the requested variant.");entries.Add(new(d.AssetId,scene.SceneId,dep[0].Sequence,d.PhysicalPath,d.DurationMilliseconds.Value,d.Width.Value,d.Height.Value,d.FrameRate.Value,source.ChannelCount>0?true:null,d.ContentIdentity,d.Checksum));}var ordered=entries.OrderBy(x=>x.Sequence).ThenBy(x=>x.AssetId,StringComparer.Ordinal).ToArray();var duration=r.AssetPlan.ExpectedDurationMilliseconds>0?r.AssetPlan.ExpectedDurationMilliseconds:ordered.Sum(x=>x.DurationMilliseconds);if(duration<=0)return Fail(DocumentaryProductionFailureCode.DurationMeasurementFailed,"Variant duration is unavailable.");return new(new(new ReadOnlyCollection<DocumentaryResolvedVariantScene>(ordered),r.MediaVariant.VariantId,r.MediaVariant.VariantType,r.CorrelationId,duration,r.Width,r.Height,r.FrameRate,r.AudioChannelCount>0),null);}
 static bool IsLowercaseSha256(string value)=>value.Length==64&&value.All(c=>c is >= '0' and <= '9' or >= 'a' and <= 'f');
 static DocumentaryVariantDependencyResolution Fail(DocumentaryProductionFailureCode c,string m)=>new(null,new(c,m)); }
public interface IDocumentaryVariantCompatibilityValidator { DocumentaryProductionFailure? Validate(DocumentaryResolvedVariantDependencies dependencies,DocumentaryMediaAssetFormat outputFormat,DocumentaryVariantAudioPolicy audioPolicy,decimal frameRateTolerance); }
public sealed class DocumentaryVariantCompatibilityValidator:IDocumentaryVariantCompatibilityValidator { public DocumentaryProductionFailure? Validate(DocumentaryResolvedVariantDependencies d,DocumentaryMediaAssetFormat f,DocumentaryVariantAudioPolicy audio,decimal tolerance){if(f!=DocumentaryMediaAssetFormat.Mp4)return new(DocumentaryProductionFailureCode.ProviderRejectedRequest,"Only MP4 output is supported.");foreach(var s in d.OrderedScenes){if(s.Width!=d.ExpectedWidth||s.Height!=d.ExpectedHeight)return new(DocumentaryProductionFailureCode.DimensionMismatch,"Scene dimensions are incompatible.");if(Math.Abs(s.FrameRate-d.ExpectedFrameRate)>tolerance)return new(DocumentaryProductionFailureCode.OutputFormatInvalid,"Scene frame rates are incompatible.");if(audio==DocumentaryVariantAudioPolicy.RequireAudio&&s.HasAudio==false)return new(DocumentaryProductionFailureCode.AudioStreamMissing,"A scene audio stream is missing.");}return null;} }
