public sealed record DocumentaryVariantCompositionProviderResponse(string? OutputPath,DocumentaryProductionFailure? Failure=null,int? ExitCode=null,long? ElapsedMilliseconds=null,string? SanitizedStandardErrorHash=null,string? CompositionMode=null){public bool Succeeded=>Failure is null&&!string.IsNullOrWhiteSpace(OutputPath);}
