public sealed record DocumentaryVariantVideoInspection(bool Succeeded,string? Format,long DurationMilliseconds,int Width,int Height,decimal FrameRate,bool HasVideo,bool HasAudio,DocumentaryProductionFailure? Failure=null);
public interface IDocumentaryVariantVideoInspector { Task<DocumentaryVariantVideoInspection> InspectAsync(string path,CancellationToken cancellationToken); }
public sealed class DocumentaryVariantVideoInspector(IDocumentaryMediaProbe probe):IDocumentaryVariantVideoInspector { public async Task<DocumentaryVariantVideoInspection> InspectAsync(string path,CancellationToken token){token.ThrowIfCancellationRequested();if(!File.Exists(path))return Fail(DocumentaryProductionFailureCode.OutputArtifactMissing,"The variant video is missing.");if(new FileInfo(path).Length==0)return Fail(DocumentaryProductionFailureCode.OutputArtifactEmpty,"The variant video is empty.");var p=await probe.ProbeAsync(path,token);if(!p.Succeeded)return Fail(p.Failure?.Code??DocumentaryProductionFailureCode.OutputFormatInvalid,"The variant video could not be inspected.");if(p.HasVideoStream!=true)return Fail(DocumentaryProductionFailureCode.VideoStreamMissing,"The variant has no video stream.");if(p.DurationMilliseconds is null or <=0||p.Width is null or <=0||p.Height is null or <=0||p.FrameRate is null or <=0)return Fail(DocumentaryProductionFailureCode.OutputFormatInvalid,"Variant metadata is invalid.");return new(true,p.ContainerFormat,p.DurationMilliseconds.Value,p.Width.Value,p.Height.Value,p.FrameRate.Value,true,p.HasAudioStream==true);}static DocumentaryVariantVideoInspection Fail(DocumentaryProductionFailureCode c,string m)=>new(false,null,0,0,0,0,false,false,new(c,m)); }
