public interface IDocumentaryProductionVariantCompositionAdapter { Task<DocumentaryProductionVariantCompositionAdapterResult> ComposeAsync(DocumentaryVariantCompositionRequest request,DocumentaryProductionExecutionContext executionContext,DocumentaryProductionAttemptContext attemptContext,DocumentaryProductionWorkspace workspace,CancellationToken cancellationToken); }
public sealed class ExistingDocumentaryVariantCompositionAdapter(IOptions<DocumentaryVariantCompositionAdapterOptions> options,IDocumentaryVariantDependencyResolver resolver,IDocumentaryVariantCompatibilityValidator compatibility,IEnumerable<IDocumentaryVariantCompositionProviderBinding> bindings,IDocumentaryVariantVideoInspector inspector,IDocumentaryProductionWorkspaceManager workspaces,IDocumentaryPhysicalArtifactInspector artifacts,IDocumentaryPhysicalArtifactDescriptorValidator validator,IDocumentaryPhysicalArtifactRegistry registry,IDocumentaryProductionDiagnosticsWriter diagnostics,IDocumentaryProductionFailureNormalizer failures):IDocumentaryProductionVariantCompositionAdapter {
 public async Task<DocumentaryProductionVariantCompositionAdapterResult> ComposeAsync(DocumentaryVariantCompositionRequest r,DocumentaryProductionExecutionContext execution,DocumentaryProductionAttemptContext attempt,DocumentaryProductionWorkspace workspace,CancellationToken token){token.ThrowIfCancellationRequested();DocumentaryProductionVariantCompositionAdapterResult Fail(DocumentaryProductionFailureCode c,string m)=>DocumentaryProductionVariantCompositionAdapterResult.Failed(new(c,m),r);if(!options.Value.Enabled)return Fail(DocumentaryProductionFailureCode.AdapterUnavailable,"Variant composition is disabled.");var selected=bindings.Where(x=>x.ProviderId==DocumentaryVariantCompositionProviderIds.ExistingFFmpegVariantComposer).ToArray();if(selected.Length!=1)return Fail(DocumentaryProductionFailureCode.AdapterUnavailable,"Exactly one FFmpeg variant binding is required.");var resolved=await resolver.ResolveAsync(r,workspace,token);if(!resolved.Succeeded)return DocumentaryProductionVariantCompositionAdapterResult.Failed(resolved.Failure!,r);var d=resolved.Dependencies!;var audio=d.RequiresAudio?DocumentaryVariantAudioPolicy.RequireAudio:DocumentaryVariantAudioPolicy.VideoOnly;var invalid=compatibility.Validate(d,r.VideoFormat,audio,options.Value.FrameRateTolerance);if(invalid is not null)return DocumentaryProductionVariantCompositionAdapterResult.Failed(invalid,r);var dir=workspaces.GetAttemptDirectory(workspace,DocumentaryProductionOperationKind.VariantComposition,r.AssetPlan.AssetId,attempt.AttemptNumber);Directory.CreateDirectory(dir);var request=new DocumentaryVariantCompositionProviderRequest(r.AssetPlan.AssetId,r.AssetPlan.SourceInstructionId,d.VariantId,d.VariantType,r.MediaVariant.Language,r.CorrelationId,attempt.AttemptNumber,dir,Path.Combine(dir,"provider-variant.mp4"),r.VideoFormat,r.Width,r.Height,r.FrameRate,d.ExpectedDurationMilliseconds,new ReadOnlyCollection<string>(d.OrderedScenes.Select(x=>x.PhysicalPath).ToArray()),d.OrderedScenes,audio,"ConcatDemuxerFinalReencode",r.Height>r.Width?"ShortsFinal":"YouTubeLongFinal","AAC");DocumentaryVariantCompositionProviderResponse response;try{response=await selected[0].ComposeAsync(request,token);}catch(OperationCanceledException) when(token.IsCancellationRequested){throw;}catch(Exception e){return DocumentaryProductionVariantCompositionAdapterResult.Failed(failures.Normalize(e,DocumentaryProductionOperationKind.VariantComposition,false),r);}if(response is null||!response.Succeeded)return DocumentaryProductionVariantCompositionAdapterResult.Failed(response?.Failure??new(DocumentaryProductionFailureCode.ProviderInvalidResponse,"The FFmpeg binding returned an invalid response."),r);if(!DocumentaryPathComparison.IsBelow(dir,response.OutputPath!))return Fail(DocumentaryProductionFailureCode.ProviderInvalidResponse,"Provider output is outside its attempt directory.");DocumentaryVariantVideoInspection measured;try{measured=await inspector.InspectAsync(response.OutputPath!,token);}catch(OperationCanceledException) when(token.IsCancellationRequested){throw;}catch(Exception e){return DocumentaryProductionVariantCompositionAdapterResult.Failed(failures.Normalize(e,DocumentaryProductionOperationKind.VariantComposition,false),r);}if(!measured.Succeeded)return DocumentaryProductionVariantCompositionAdapterResult.Failed(measured.Failure!,r);if(measured.Width!=r.Width||measured.Height!=r.Height)return Fail(DocumentaryProductionFailureCode.DimensionMismatch,"Variant dimensions do not match.");if(Math.Abs(measured.FrameRate-r.FrameRate)>options.Value.FrameRateTolerance)return Fail(DocumentaryProductionFailureCode.OutputFormatInvalid,"Variant frame rate does not match.");if(Math.Abs(measured.DurationMilliseconds-d.ExpectedDurationMilliseconds)>options.Value.DurationToleranceMilliseconds)return Fail(DocumentaryProductionFailureCode.DurationMeasurementFailed,"Variant duration is outside tolerance.");if(d.RequiresAudio&&!measured.HasAudio)return Fail(DocumentaryProductionFailureCode.AudioStreamMissing,"Required audio is missing.");try{var final=workspaces.GetFinalArtifactPath(workspace,d.VariantId,null,DocumentaryPhysicalArtifactKind.VariantVideo,r.AssetPlan.AssetId,"mp4");await workspaces.FinalizeArtifactAsync(workspace,response.OutputPath!,final,true,token);var descriptor=await artifacts.InspectAsync(new(r.AssetPlan.AssetId,final,"video/mp4",selected[0].ProviderId,attempt.AttemptNumber,r.CorrelationId),token);descriptor=descriptor with{DurationMilliseconds=measured.DurationMilliseconds,Width=measured.Width,Height=measured.Height,FrameRate=measured.FrameRate};if(validator.Validate(descriptor).Count>0)return Fail(DocumentaryProductionFailureCode.OutputFormatInvalid,"The finalized variant descriptor is invalid.");await registry.RegisterAsync(descriptor,DocumentaryPhysicalArtifactKind.VariantVideo,token);var diag=$"variant-{Safe(r.AssetPlan.AssetId)}-{attempt.AttemptNumber:D2}.json";await diagnostics.WriteAsync(workspace.DiagnosticsDirectory,diag,new{execution.ExecutionId,r.CorrelationId,r.AssetPlan.AssetId,r.AssetPlan.SourceInstructionId,VariantId=d.VariantId,VariantType=d.VariantType.ToString(),Language=r.MediaVariant.Language.ToString(),ProviderId=selected[0].ProviderId,Attempt=attempt.AttemptNumber,SceneCount=d.SceneCount,OrderedSceneAssetIds=d.OrderedScenes.Select(x=>x.AssetId),OrderedSceneContentIdentities=d.OrderedScenes.Select(x=>x.ContentIdentity),RequestedFormat=r.VideoFormat.ToString(),ActualFormat=measured.Format,ExpectedDurationMilliseconds=d.ExpectedDurationMilliseconds,ActualDurationMilliseconds=measured.DurationMilliseconds,RequestedWidth=r.Width,ActualWidth=measured.Width,RequestedHeight=r.Height,ActualHeight=measured.Height,RequestedFrameRate=r.FrameRate,ActualFrameRate=measured.FrameRate,AudioPolicy=audio.ToString(),CompositionMode=request.CompositionMode,descriptor.Checksum,descriptor.ContentIdentity,SanitizedStandardErrorHash=response.SanitizedStandardErrorHash,Outcome="Succeeded"},token);if(!options.Value.RetainProviderNativeVideo)await workspaces.CleanupSuccessfulAttemptAsync(workspace,dir,token);return new(true,descriptor,null,selected[0].ProviderId,selected[0].ProviderId,d.VariantId,d.VariantType,r.VideoFormat,d.SceneCount,measured.DurationMilliseconds,measured.Width,measured.Height,measured.FrameRate,true,measured.HasAudio,diag);}catch(OperationCanceledException) when(token.IsCancellationRequested){throw;}catch(Exception e){return DocumentaryProductionVariantCompositionAdapterResult.Failed(failures.Normalize(e,DocumentaryProductionOperationKind.VariantComposition,false),r);}}
